package demo.ledger.fees;

import demo.ledger.money.Money;
import demo.ledger.money.MoneyOperation;
import demo.ledger.money.RoundingPolicy;
import java.math.BigDecimal;

public final class CustodyFeeCalculator {

    private static final BigDecimal ANNUAL_RATE = new BigDecimal("0.0075");
    private static final BigDecimal MONTHS = BigDecimal.valueOf(12);

    public Money monthlyFee(Money portfolioValue) {
        BigDecimal fee = portfolioValue.amount().multiply(ANNUAL_RATE).divide(MONTHS, RoundingPolicy.INTERMEDIATE);
        return RoundingPolicy.round(MoneyOperation.CUSTODY_FEE, fee, portfolioValue.currency());
    }
}

