package demo.ledger.fx;

import demo.ledger.money.Money;
import demo.ledger.money.MoneyOperation;
import demo.ledger.money.RoundingPolicy;
import java.math.BigDecimal;
import java.util.Currency;

public final class FxConverter {

    private final FxRates rates;

    public FxConverter(FxRates rates) {
        this.rates = rates;
    }

    public Money convert(Money amount, Currency target) {
        BigDecimal rate = rates.rate(amount.currency(), target);
        return RoundingPolicy.round(MoneyOperation.FX_CONVERSION, amount.amount().multiply(rate), target);
    }
}

