package demo.ledger.fx;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.Currency;
import java.util.Map;

public final class FxRates {

    private final Map<Currency, BigDecimal> chfPerUnit;

    public FxRates(Map<Currency, BigDecimal> chfPerUnit) {
        this.chfPerUnit = Map.copyOf(chfPerUnit);
    }

    public BigDecimal rate(Currency from, Currency to) {
        return chfPer(from).divide(chfPer(to), to.getDefaultFractionDigits(), RoundingMode.HALF_EVEN);
    }

    private BigDecimal chfPer(Currency currency) {
        BigDecimal rate = chfPerUnit.get(currency);
        if (rate == null) {
            throw new IllegalArgumentException("no CHF rate for " + currency);
        }
        return rate;
    }
}

