package demo.ledger.money;

import java.math.BigDecimal;
import java.math.MathContext;
import java.math.RoundingMode;
import java.util.Currency;
import java.util.EnumMap;
import java.util.Map;

public final class RoundingPolicy {

    public static final MathContext INTERMEDIATE = MathContext.DECIMAL128;

    private static final Map<MoneyOperation, RoundingMode> MODES = new EnumMap<>(Map.of(
            MoneyOperation.POSTING, RoundingMode.HALF_EVEN,
            MoneyOperation.CUSTODY_FEE, RoundingMode.HALF_EVEN,
            MoneyOperation.FX_CONVERSION, RoundingMode.HALF_EVEN,
            MoneyOperation.POSITION_VALUATION, RoundingMode.HALF_EVEN,
            // The clearing counterparty's rulebook (section 7.3) rounds each settlement amount half up.
            MoneyOperation.CLEARING_SETTLEMENT, RoundingMode.HALF_UP));

    private RoundingPolicy() {
    }

    public static Money round(MoneyOperation operation, BigDecimal amount, Currency currency) {
        RoundingMode mode = MODES.get(operation);
        return new Money(amount.setScale(currency.getDefaultFractionDigits(), mode), currency);
    }
}

