package demo.ledger.posting;

import demo.ledger.money.Money;
import demo.ledger.money.RoundingPolicy;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.Clock;
import java.util.List;

public final class InterestPosting {

    static final String INTEREST_EXPENSE_ACCOUNT = "4100-interest-expense";
    private static final BigDecimal DAYS_PER_YEAR = BigDecimal.valueOf(365);

    private final Ledger ledger;
    private final Clock clock;

    public InterestPosting(Ledger ledger, Clock clock) {
        this.ledger = ledger;
        this.clock = clock;
    }

    public JournalEntry postDailyInterest(String accountId, Money balance, BigDecimal annualRate) {
        BigDecimal interest = balance.amount().multiply(annualRate).divide(DAYS_PER_YEAR, RoundingPolicy.INTERMEDIATE);
        Money amount = new Money(
                interest.setScale(balance.currency().getDefaultFractionDigits(), RoundingMode.HALF_UP),
                balance.currency());
        JournalEntry entry = JournalEntry.of(BookingDate.today(clock), List.of(
                new Posting(INTEREST_EXPENSE_ACCOUNT, amount.negate()),
                new Posting(accountId, amount)));
        ledger.book(entry);
        return entry;
    }
}

