package demo.ledger.posting;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.Currency;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.UUID;

public record JournalEntry(UUID id, LocalDate valueDate, List<Posting> postings) {

    public JournalEntry {
        Objects.requireNonNull(id, "id");
        Objects.requireNonNull(valueDate, "valueDate");
        postings = List.copyOf(postings);
        if (postings.size() < 2) {
            throw new IllegalArgumentException("a journal entry needs at least two postings");
        }
        Map<Currency, BigDecimal> totals = new HashMap<>();
        for (Posting posting : postings) {
            totals.merge(posting.amount().currency(), posting.amount().amount(), BigDecimal::add);
        }
        totals.forEach((currency, total) -> {
            if (total.signum() != 0) {
                throw new IllegalArgumentException("postings in " + currency + " sum to " + total + ", not zero");
            }
        });
    }

    public static JournalEntry of(LocalDate valueDate, List<Posting> postings) {
        return new JournalEntry(UUID.randomUUID(), valueDate, postings);
    }
}

