package demo.ledger.valuation;

import demo.ledger.money.Money;
import demo.ledger.money.MoneyOperation;
import demo.ledger.money.RoundingPolicy;
import java.math.BigDecimal;
import java.math.RoundingMode;

public final class PositionValuation {

    public Money marketValue(Position position, Quote quote) {
        if (!position.isin().equals(quote.isin())) {
            throw new IllegalArgumentException(quote.isin() + " does not price " + position.isin());
        }
        int minorUnits = quote.currency().getDefaultFractionDigits();
        BigDecimal unitPrice = quote.price().setScale(minorUnits, RoundingMode.HALF_EVEN);
        return RoundingPolicy.round(
                MoneyOperation.POSITION_VALUATION, unitPrice.multiply(position.quantity()), quote.currency());
    }
}

