package demo.ledger.valuation;

import java.math.BigDecimal;
import java.time.Instant;
import java.util.Currency;
import java.util.Objects;

public record Quote(String isin, BigDecimal price, Currency currency, Instant asOf) {

    public static final int PRICE_SCALE = 8;

    public Quote {
        Objects.requireNonNull(isin, "isin");
        Objects.requireNonNull(price, "price");
        Objects.requireNonNull(currency, "currency");
        Objects.requireNonNull(asOf, "asOf");
        if (price.scale() > PRICE_SCALE) {
            throw new IllegalArgumentException(isin + ": price " + price + " has more than " + PRICE_SCALE + " decimals");
        }
        price = price.setScale(PRICE_SCALE);
    }
}

