package demo.ledger.fx;

import static org.junit.jupiter.api.Assertions.assertEquals;

import demo.ledger.money.Money;
import java.math.BigDecimal;
import java.util.Currency;
import java.util.Map;
import org.junit.jupiter.api.Test;

class FxConverterTest {

    private static final Currency CHF = Currency.getInstance("CHF");
    private static final Currency EUR = Currency.getInstance("EUR");

    @Test
    void convertsEurosToFrancs() {
        // Arrange
        FxConverter converter = new FxConverter(new FxRates(Map.of(CHF, BigDecimal.ONE, EUR, new BigDecimal("0.95"))));

        // Act
        Money converted = converter.convert(new Money(new BigDecimal("100.00"), EUR), CHF);

        // Assert
        assertEquals(new Money(new BigDecimal("95.00"), CHF), converted);
    }
}

